const unfollowUser = `-- name: UnfollowUser :execrows
DELETE FROM user_follows
WHERE follower_user_ref = $1
  AND followee_user_ref = $2
`

type UnfollowUserParams struct {
	FollowerUserRef int64
	FolloweeUserRef int64
}

// Rows-affected so the handler can 404 cleanly when the caller
// wasn't following the target. The handler maps "0 rows deleted"
// to 204 anyway (idempotent unfollow) but having the count makes
// audit + metrics writers happy.
func (q *Queries) UnfollowUser(ctx context.Context, arg UnfollowUserParams) (int64, error) {
	result, err := q.db.Exec(ctx, unfollowUser, arg.FollowerUserRef, arg.FolloweeUserRef)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const unlikeTarget = `-- name: UnlikeTarget :execrows
DELETE FROM likes
WHERE target_kind = $1 AND target_id = $2 AND rs_user_id = $3
`

type UnlikeTargetParams struct {
	TargetKind string
	TargetID   pgtype.UUID
	RsUserID   int64
}

// Returns 1 if a row was removed (and the trigger decremented the
// counter), 0 if the user didn't have a like to remove. Handler maps
// 0 to a 404 so the client knows its optimistic update was wrong.
func (q *Queries) UnlikeTarget(ctx context.Context, arg UnlikeTargetParams) (int64, error) {
	result, err := q.db.Exec(ctx, unlikeTarget, arg.TargetKind, arg.TargetID, arg.RsUserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateAnnotationData = `-- name: UpdateAnnotationData :one
UPDATE comments SET
    body            = COALESCE($1, body),
    annotation_data = $2,
    edited_at       = CASE WHEN $1 IS NOT NULL THEN NOW() ELSE edited_at END,
    updated_at      = NOW()
WHERE id = $3 AND deleted_at IS NULL
RETURNING id, target_kind, target_id, parent_id, root_id, depth,
          author_user_ref, body, body_html,
          annotation_type, annotation_data,
          like_count, edited_at, deleted_at,
          origin_server_id, created_at, updated_at
`

type UpdateAnnotationDataParams struct {
	Body           *string
	AnnotationData []byte
	ID             pgtype.UUID
}

// Narrow update for the doc-viewer's "change color / change style /
// toggle resolved / edit comment body" actions. Replaces the full
// annotation_data blob (the panel sends the merged shape it wants)
// and optionally updates the body text. Caller must guarantee the
// comment is an annotation; we don't enforce annotation_type here so
// the same query serves whiteboard PATCH too if needed later.
func (q *Queries) UpdateAnnotationData(ctx context.Context, arg UpdateAnnotationDataParams) (Comment, error) {
	row := q.db.QueryRow(ctx, updateAnnotationData, arg.Body, arg.AnnotationData, arg.ID)
	var i Comment
	err := row.Scan(
		&i.ID,
		&i.TargetKind,
		&i.TargetID,
		&i.ParentID,
		&i.RootID,
		&i.Depth,
		&i.AuthorUserRef,
		&i.Body,
		&i.BodyHtml,
		&i.AnnotationType,
		&i.AnnotationData,
		&i.LikeCount,
		&i.EditedAt,
		&i.DeletedAt,
		&i.OriginServerID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

